export function GridItem({
  colSpan = {{colSpan}},
  rowSpan = {{rowSpan}},
  justifySelf = "{{justifySelf}}",
  alignSelf = "{{alignSelf}}",
}) {
  const cell = { background: "#A8E6C1", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 600 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="A 3 by 2 grid; the highlighted target cell's column span, row span, justify-self and align-self are adjustable">
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gridAutoRows: 56, gap: 8,
        background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box" }}>
        <div style={{ ...cell, background: "#F5C2E0", fontWeight: 700, gridColumn: `span ${colSpan}`, gridRow: `span ${rowSpan}`, justifySelf, alignSelf }}>target</div>
        <div style={cell}>b</div><div style={cell}>c</div><div style={cell}>d</div><div style={cell}>e</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        span {colSpan}&times;{rowSpan} &middot; justify-self: {justifySelf} &middot; align-self: {alignSelf}
      </p>
    </div>
  );
}
